@import "@fontsource-variable/montserrat";

/* Light (faithful): warm paper sections, white cards, warm ink, acid lime and baby pink. */
:root {
  --background: rgb(255 255 255);
  --foreground: rgb(23 19 19);
  --card: rgb(255 255 255);
  --card-foreground: rgb(23 19 19);
  --popover: rgb(255 255 255);
  --popover-foreground: rgb(23 19 19);
  --primary: rgb(200 255 18);
  --primary-foreground: rgb(23 19 19);
  --secondary: rgb(178 174 173);
  --secondary-foreground: rgb(23 19 19);
  --muted: rgb(239 234 233);
  --muted-foreground: rgb(23 19 19 / 73%);
  --accent: rgb(23 19 19 / 7%);
  --accent-foreground: rgb(23 19 19);
  --destructive: rgb(214 52 52);
  --destructive-foreground: rgb(255 255 255);
  --border: rgb(23 19 19 / 16%);
  --input: rgb(23 19 19 / 25%);
  --ring: rgb(23 19 19);
  --highlight: rgb(255 199 216);
  --highlight-foreground: rgb(23 19 19);
  --glow: rgb(200 255 18);
  --chart-1: rgb(200 255 18);
  --chart-2: rgb(255 199 216);
  --chart-3: rgb(23 19 19);
  --chart-4: rgb(178 174 173);
  --chart-5: rgb(120 150 10);
  --sidebar: rgb(239 234 233);
  --sidebar-foreground: rgb(23 19 19);
  --sidebar-primary: rgb(200 255 18);
  --sidebar-primary-foreground: rgb(23 19 19);
  --sidebar-accent: rgb(23 19 19 / 7%);
  --sidebar-accent-foreground: rgb(23 19 19);
  --sidebar-border: rgb(23 19 19 / 16%);
  --sidebar-ring: rgb(23 19 19);

  --typeface-body: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Montserrat Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1.5rem;
  --page-width: 84rem;
  --page-gutter: 1rem;
  --section-y: 4rem;
}

/* Dark (sibling): the CTA panel's warm ink as the page, slightly lifted ink cards,
   the same lime and pink. */
.dark {
  --background: rgb(23 19 19);
  --foreground: rgb(246 242 241);
  --card: rgb(34 29 29);
  --card-foreground: rgb(246 242 241);
  --popover: rgb(34 29 29);
  --popover-foreground: rgb(246 242 241);
  --primary: rgb(200 255 18);
  --primary-foreground: rgb(23 19 19);
  --secondary: rgb(52 46 45);
  --secondary-foreground: rgb(246 242 241);
  --muted: rgb(29 24 24);
  --muted-foreground: rgb(255 255 255 / 72%);
  --accent: rgb(255 255 255 / 8%);
  --accent-foreground: rgb(246 242 241);
  --destructive: rgb(240 96 96);
  --destructive-foreground: rgb(23 19 19);
  --border: rgb(255 255 255 / 14%);
  --input: rgb(255 255 255 / 22%);
  --ring: rgb(200 255 18);
  --highlight: rgb(255 199 216);
  --highlight-foreground: rgb(23 19 19);
  --glow: rgb(200 255 18);
  --chart-1: rgb(200 255 18);
  --chart-2: rgb(255 199 216);
  --chart-3: rgb(246 242 241);
  --chart-4: rgb(140 134 133);
  --chart-5: rgb(150 190 20);
  --sidebar: rgb(29 24 24);
  --sidebar-foreground: rgb(246 242 241);
  --sidebar-primary: rgb(200 255 18);
  --sidebar-primary-foreground: rgb(23 19 19);
  --sidebar-accent: rgb(255 255 255 / 8%);
  --sidebar-accent-foreground: rgb(246 242 241);
  --sidebar-border: rgb(255 255 255 / 14%);
  --sidebar-ring: rgb(200 255 18);
}
